import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
format_phone = target.format_phone


def test_format_standard():
    # Spec: format exactly 10 digits as (XXX) XXX-XXXX
    assert format_phone("2065551234") == "(206) 555-1234"


def test_format_zero_area():
    assert format_phone("0000000000") == "(000) 000-0000"


def test_format_leading_zeros():
    assert format_phone("0105550123") == "(010) 555-0123"


def test_non_string_raises_typeerror():
    try:
        format_phone(2065551234)
    except TypeError:
        pass
    else:
        raise AssertionError("expected TypeError for non-string")


def test_too_few_digits_raises():
    try:
        format_phone("123456789")  # 9 digits
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for 9 digits")


def test_too_many_digits_raises():
    try:
        format_phone("12345678901")  # 11 digits
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for 11 digits")


def test_non_digit_raises():
    try:
        format_phone("20655a1234")
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for non-digit char")


def test_separators_not_normalized():
    # Spec: separators/spaces should raise ValueError, not be normalized
    try:
        format_phone("(206) 555-1234")
    except ValueError:
        pass
    else:
        raise AssertionError("expected ValueError for already-separated input")


def test_empty_raises():
    try:
        format_phone("")
