target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
merge_inventory = target.merge_inventory


def test_no_overlap():
    """Non-overlapping SKUs: both sets appear in result."""
    base = {"A": 1, "B": 2}
    incoming = {"C": 3}
    result = merge_inventory(base, incoming)
    assert result == {"A": 1, "B": 2, "C": 3}


def test_matching_skus_sum():
    """Matching SKUs have counts added together."""
    base = {"X": 5, "Y": 10}
    incoming = {"X": 3, "Z": 1}
    result = merge_inventory(base, incoming)
    assert result["X"] == 8
    assert result["Y"] == 10
    assert result["Z"] == 1


def test_empty_inputs():
    """Both inputs empty: result is empty."""
    assert merge_inventory({}, {}) == {}


def test_one_empty():
    """One input empty: result equals the other."""
    base = {"A": 1}
    incoming = {}
    assert merge_inventory(base, incoming) == {"A": 1}

    base2 = {}
    incoming2 = {"B": 2}
    assert merge_inventory(base2, incoming2) == {"B": 2}


def test_zero_count_valid():
    """Zero is a valid non-negative count."""
    result = merge_inventory({"A": 0}, {"A": 5})
    assert result["A"] == 5


def test_both_zero():
    """Both counts zero: sum is zero."""
    result = merge_inventory({"A": 0}, {"A": 0})
    assert result["A"] == 0


def test_no_mutation_base():
    """Base dict must not be mutated."""
    base = {"A": 1, "B": 2}
    incoming = {"A": 3}
    base_copy = dict(base)
    _ = merge_inventory(base, incoming)
    assert base == base_copy


def test_no_mutation_incoming():
    """Incoming dict must not be mutated."""
    base = {"A": 1}
    incoming = {"A": 3, "C": 7}
    incoming_copy = dict(incoming)
    _ = merge_inventory(base, incoming)
    assert incoming == incoming_copy


def test_returns_new_dict():
    """Result is a new dict, not either input."""
    base = {"A": 1}
    incoming = {"A": 2}
    result = merge_inventory(base, incoming)
    assert result is not base
    assert result is not incoming


def test_type_error_base_not_dict():
    """Non-dict base raises TypeError."""
    try:
        merge_inventory("not a dict", {})
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_type_error_incoming_not_dict():
    """Non-dict incoming raises TypeError."""
    try:
        merge_inventory({}, ["not a dict"])
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_type_error_non_int_count_base():
    """Non-int count in base raises TypeError."""
    try:
        merge_inventory({"A": "five"}, {})
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_type_error_non_int_count_incoming():
    """Non-int count in incoming raises TypeError."""
    try:
        merge_inventory({}, {"A": 1.5})
        assert False, "Expected TypeError"
    except TypeError:
        pass


def test_value_error_negative_base():
    """Negative count in base raises ValueError."""
    try:
        merge_inventory({"A": -1}, {})
        assert False, "Expected ValueError"
    except ValueError:
        pass


def test_value_error_negative_incoming():
    """Negative count in incoming raises ValueError."""
    try:
        merge_inventory({}, {"A": -5})
        assert False, "Expected ValueError"
    except ValueError:
        pass


def test_value_error_empty_sku():
    """Empty string SKU raises ValueError."""
    try:
        merge_inventory({"": 1}, {})
        assert False, "Expected ValueError"
    except ValueError:
        pass


def test_value_error_non_str_sku():
    """Non-string SKU raises ValueError."""
    try:
        merge_inventory({123: 5}, {})
        assert False, "Expected ValueError"
    except ValueError:
        pass


def test_large_counts():
    """Large counts are handled correctly."""
    base = {"A": 1000000}
    incoming = {"A": 999999}
