    """Base dict must not be mutated."""
    base = {"A": 1, "B": 2}
    incoming = {"A": 3}
    base_copy = dict(base)
    _ = merge_inventory(base, incoming)
    assert base == base_copy


def test_no_mutation_incoming():
    """Incoming dict must not be mutated."""
    base = {"A": 1}
