{"success": true, "content": "from typing import List


def _require_lines(lines: List[str]) -> List[str]:
    if not isinstance(lines, list):
        raise TypeError("lines must be a list")
    for line in lines:
        if not isinstance(line, str):
            raise TypeError("lines must contain strings")
    return lines


def _clean_line(line: str) -> str:
    return line.strip()


def _should_keep(line: str) -> bool:
    return line != ""


def compact_whitespace(lines: List[str]) -> List[str]:
    """Strip each line and omit empty results.

    Whitespace-only lines should not appear in the output. The relative order of
    non-empty stripped lines should be preserved.
    """
    lines = _require_lines(lines)
    result = []
    for line in lines:
        stripped = _clean_line(line)
        if _should_keep(stripped):
            result.append(stripped)
    return result
"}

{"success": true, "content": "def _require_digits(digits: str) -> str:
    if not isinstance(digits, str):
        raise TypeError("digits must be a string")
    if len(digits) != 10 or not digits.isdigit():
        raise ValueError("digits must contain exactly 10 digits")
    return digits


def _area_code(digits: str) -> str:
    return digits[:3]


def _prefix(digits: str) -> str:
    return digits[3:6]


def _line_number(digits: str) -> str:
    return digits[6:]


def format_phone(digits: str) -> str:
    """Format exactly 10 digits as (XXX) XXX-XXXX.

    Only plain digit strings are accepted. Separators, spaces, country codes,
    and missing digits should raise ValueError rather than being normalized.
    """
    digits = _require_digits(digits)
    area = _area_code(digits)
    prefix = _prefix(digits)
    line = _line_number(digits)
    return f"{area}-{prefix}-{line}"
"}

