    """Matching SKUs have counts added together."""
    base = {"X": 5, "Y": 10}
    incoming = {"X": 3, "Z": 1}
    result = merge_inventory(base, incoming)
    assert result["X"] == 8
    assert result["Y"] == 10
    assert result["Z"] == 1


