    base = {"A": 1, "B": 2}
    incoming = {"C": 3}
    result = merge_inventory(base, incoming)
    assert result == {"A": 1, "B": 2, "C": 3}


def test_matching_skus_sum():
    """Matching SKUs have counts added together."""
    base = {"X": 5, "Y": 10}
    incoming = {"X": 3, "Z": 1}
    result = merge_inventory(base, incoming)
    assert result["X"] == 8
    assert result["Y"] == 10
    assert result["Z"] == 1


def test_empty_inputs():
    """Both inputs empty: result is empty."""
    assert merge_inventory({}, {}) == {}


def test_one_empty():
    """One input empty: result equals the other."""
    base = {"A": 1}
    incoming = {}
    assert merge_inventory(base, incoming) == {"A": 1}

    base2 = {}
    incoming2 = {"B": 2}
    assert merge_inventory(base2, incoming2) == {"B": 2}


def test_zero_count_valid():
    """Zero is a valid non-negative count."""
    result = merge_inventory({"A": 0}, {"A": 5})
    assert result["A"] == 5


